-- PostgreSQL ekvivalenti: db/migrations/001_init.sql + 002_views_triggers.sql (opsional, docker-compose.postgres.yml ilə).
-- Server runtime-da yalnız SQLite ilə işləyir; bu fayl sxemin portativ olduğunu göstərmək və PostgreSQL-də SQL praktikası üçündür.
-- SQLite → PostgreSQL fərqləri (tədris üçün):
--   INTEGER PRIMARY KEY AUTOINCREMENT  → INTEGER GENERATED BY DEFAULT AS IDENTITY
--   strftime('%Y-%m-%dT%H:%M:%SZ','now') → iso_now() (aşağıda funksiya)
--   json_valid(x)                       → (x::jsonb IS NOT NULL)
--   REAL                                → DOUBLE PRECISION
--   date(x) / date('now')               → substr(x, 1, 10) / to_char(CURRENT_DATE, 'YYYY-MM-DD')
--   CREATE TRIGGER ... BEGIN ... END     → trigger FUNCTION (plpgsql) + CREATE TRIGGER ... EXECUTE FUNCTION
-- Vaxt sahələri SQLite ilə eyni qalsın deyə TEXT (ISO-8601) saxlanılır.

CREATE FUNCTION iso_now() RETURNS TEXT LANGUAGE sql STABLE AS
$$ SELECT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') $$;

-- ============================================================ AUTH
CREATE TABLE users (
  id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username      TEXT    NOT NULL UNIQUE,
  password_hash TEXT    NOT NULL,
  full_name     TEXT    NOT NULL,
  email         TEXT    NOT NULL UNIQUE,
  role          TEXT    NOT NULL DEFAULT 'USER' CHECK (role IN ('USER', 'ADMIN')),
  created_at    TEXT    NOT NULL DEFAULT iso_now(),
  updated_at    TEXT    NOT NULL DEFAULT iso_now()
);

CREATE TABLE user_scopes (
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  scope   TEXT    NOT NULL,
  PRIMARY KEY (user_id, scope)
);

CREATE TABLE refresh_tokens (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash TEXT    NOT NULL UNIQUE,
  expires_at TEXT    NOT NULL,
  revoked_at TEXT,
  created_at TEXT    NOT NULL DEFAULT iso_now()
);
CREATE INDEX idx_refresh_tokens_user ON refresh_tokens(user_id);

CREATE TABLE api_keys (
  id            INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  key_hash      TEXT    NOT NULL UNIQUE,
  owner_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name          TEXT    NOT NULL,
  active        INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  created_at    TEXT    NOT NULL DEFAULT iso_now()
);

CREATE TABLE oauth_clients (
  client_id          TEXT PRIMARY KEY,
  client_secret_hash TEXT NOT NULL,
  name               TEXT NOT NULL,
  redirect_uris      TEXT NOT NULL CHECK ((redirect_uris::jsonb) IS NOT NULL)
);

CREATE TABLE oauth_codes (
  code         TEXT    PRIMARY KEY,
  client_id    TEXT    NOT NULL REFERENCES oauth_clients(client_id) ON DELETE CASCADE,
  user_id      INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  scope        TEXT    NOT NULL,
  redirect_uri TEXT    NOT NULL,
  expires_at   TEXT    NOT NULL,
  used_at      TEXT,
  created_at   TEXT    NOT NULL DEFAULT iso_now()
);

-- ============================================================ BANK + VALYUTA
CREATE TABLE currencies (
  code   TEXT PRIMARY KEY CHECK (length(code) = 3 AND code = upper(code)),
  name   TEXT NOT NULL,
  symbol TEXT NOT NULL
);

CREATE TABLE accounts (
  id            TEXT    PRIMARY KEY,
  owner_id      INTEGER NOT NULL REFERENCES users(id),
  currency      TEXT    NOT NULL REFERENCES currencies(code),
  balance_minor INTEGER NOT NULL DEFAULT 0 CHECK (balance_minor >= 0),
  type          TEXT    NOT NULL CHECK (type IN ('CURRENT', 'SAVINGS')),
  opened_at     TEXT    NOT NULL,
  updated_at    TEXT    NOT NULL DEFAULT iso_now()
);
CREATE INDEX idx_accounts_owner ON accounts(owner_id);

CREATE TABLE cards (
  id                INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  owner_id          INTEGER NOT NULL REFERENCES users(id),
  account_id        TEXT    NOT NULL REFERENCES accounts(id),
  last4             TEXT    NOT NULL CHECK (length(last4) = 4),
  brand             TEXT    NOT NULL CHECK (brand IN ('VISA', 'MASTERCARD')),
  status            TEXT    NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'BLOCKED', 'EXPIRED')),
  status_reason     TEXT    CHECK (status_reason IN ('LOST', 'STOLEN', 'SUSPECTED_FRAUD')),
  status_changed_by INTEGER REFERENCES users(id),
  daily_limit_minor INTEGER NOT NULL CHECK (daily_limit_minor > 0),
  expires_at        TEXT    NOT NULL,
  created_at        TEXT    NOT NULL DEFAULT iso_now(),
  updated_at        TEXT    NOT NULL DEFAULT iso_now()
);
CREATE INDEX idx_cards_owner ON cards(owner_id);
CREATE INDEX idx_cards_account ON cards(account_id);

CREATE TABLE card_status_history (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  card_id    INTEGER NOT NULL REFERENCES cards(id),
  old_status TEXT    NOT NULL,
  new_status TEXT    NOT NULL,
  reason     TEXT,
  changed_by INTEGER REFERENCES users(id),
  changed_at TEXT    NOT NULL
);
CREATE INDEX idx_card_history_card ON card_status_history(card_id, changed_at);

CREATE TABLE transfers (
  id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  from_account TEXT    NOT NULL REFERENCES accounts(id),
  to_account   TEXT    NOT NULL REFERENCES accounts(id),
  amount_minor INTEGER NOT NULL CHECK (amount_minor > 0),
  currency     TEXT    NOT NULL REFERENCES currencies(code),
  status       TEXT    NOT NULL DEFAULT 'COMPLETED' CHECK (status IN ('PENDING', 'COMPLETED', 'FAILED')),
  created_by   INTEGER REFERENCES users(id),
  created_at   TEXT    NOT NULL DEFAULT iso_now(),
  CHECK (from_account <> to_account)
);

CREATE TABLE transactions (
  id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id   TEXT    NOT NULL REFERENCES accounts(id),
  type         TEXT    NOT NULL CHECK (type IN ('DEBIT', 'CREDIT')),
  amount_minor INTEGER NOT NULL CHECK (amount_minor > 0),
  currency     TEXT    NOT NULL REFERENCES currencies(code),
  description  TEXT    NOT NULL,
  transfer_id  INTEGER REFERENCES transfers(id),
  created_at   TEXT    NOT NULL DEFAULT iso_now()
);
CREATE INDEX idx_transactions_account_date ON transactions(account_id, created_at);
CREATE INDEX idx_transactions_transfer ON transactions(transfer_id);

CREATE TABLE exchange_rates (
  id        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  base      TEXT    NOT NULL REFERENCES currencies(code),
  quote     TEXT    NOT NULL REFERENCES currencies(code),
  rate      NUMERIC NOT NULL CHECK (rate > 0),
  rate_date TEXT    NOT NULL,
  UNIQUE (base, quote, rate_date),
  CHECK (base <> quote)
);
CREATE INDEX idx_exchange_rates_date ON exchange_rates(rate_date);

-- ============================================================ AVİABİLET
CREATE TABLE airports (
  code    TEXT PRIMARY KEY CHECK (length(code) = 3 AND code = upper(code)),
  city    TEXT NOT NULL,
  country TEXT NOT NULL,
  name    TEXT NOT NULL
);

CREATE TABLE flights (
  id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  flight_no    TEXT    NOT NULL,
  airline_code TEXT    NOT NULL,
  airline_name TEXT    NOT NULL,
  from_code    TEXT    NOT NULL REFERENCES airports(code),
  to_code      TEXT    NOT NULL REFERENCES airports(code),
  depart_at    TEXT    NOT NULL,
  arrive_at    TEXT    NOT NULL,
  duration_min INTEGER NOT NULL CHECK (duration_min > 0),
  stops        INTEGER NOT NULL DEFAULT 0 CHECK (stops >= 0),
  price_minor  INTEGER NOT NULL CHECK (price_minor > 0),
  currency     TEXT    NOT NULL REFERENCES currencies(code),
  seats_left   INTEGER NOT NULL CHECK (seats_left >= 0),
  CHECK (from_code <> to_code),
  CHECK (arrive_at > depart_at)
);
CREATE INDEX idx_flights_route_date ON flights(from_code, to_code, depart_at);

CREATE TABLE flight_bookings (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  flight_id   INTEGER NOT NULL REFERENCES flights(id),
  user_id     INTEGER NOT NULL REFERENCES users(id),
  passengers  INTEGER NOT NULL CHECK (passengers >= 1),
  status      TEXT    NOT NULL DEFAULT 'CONFIRMED' CHECK (status IN ('CONFIRMED', 'CANCELLED')),
  total_minor INTEGER NOT NULL CHECK (total_minor > 0),
  currency    TEXT    NOT NULL REFERENCES currencies(code),
  created_at  TEXT    NOT NULL DEFAULT iso_now(),
  updated_at  TEXT    NOT NULL DEFAULT iso_now()
);
CREATE INDEX idx_flight_bookings_user ON flight_bookings(user_id);
CREATE INDEX idx_flight_bookings_flight ON flight_bookings(flight_id);

CREATE TABLE flight_passengers (
  id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id         INTEGER NOT NULL REFERENCES flight_bookings(id) ON DELETE CASCADE,
  first_name         TEXT    NOT NULL,
  last_name          TEXT    NOT NULL,
  passport_no_masked TEXT
);
CREATE INDEX idx_flight_passengers_booking ON flight_passengers(booking_id);

-- ============================================================ OTEL
CREATE TABLE hotels (
  id                    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  city                  TEXT    NOT NULL,
  name                  TEXT    NOT NULL,
  stars                 INTEGER NOT NULL CHECK (stars BETWEEN 1 AND 5),
  price_per_night_minor INTEGER NOT NULL CHECK (price_per_night_minor > 0),
  currency              TEXT    NOT NULL REFERENCES currencies(code),
  rating                DOUBLE PRECISION NOT NULL CHECK (rating BETWEEN 0 AND 10),
  description           TEXT    NOT NULL
);
CREATE INDEX idx_hotels_city ON hotels(city);

CREATE TABLE hotel_amenities (
  hotel_id INTEGER NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,
  amenity  TEXT    NOT NULL,
  PRIMARY KEY (hotel_id, amenity)
);

CREATE TABLE hotel_rooms (
  id                    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  hotel_id              INTEGER NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,
  room_type             TEXT    NOT NULL CHECK (room_type IN ('SINGLE', 'DOUBLE', 'SUITE', 'FAMILY')),
  capacity              INTEGER NOT NULL CHECK (capacity >= 1),
  price_per_night_minor INTEGER NOT NULL CHECK (price_per_night_minor > 0)
);
CREATE INDEX idx_hotel_rooms_hotel ON hotel_rooms(hotel_id);

CREATE TABLE hotel_bookings (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  room_id     INTEGER NOT NULL REFERENCES hotel_rooms(id),
  user_id     INTEGER NOT NULL REFERENCES users(id),
  check_in    TEXT    NOT NULL,
  check_out   TEXT    NOT NULL,
  guests      INTEGER NOT NULL CHECK (guests >= 1),
  status      TEXT    NOT NULL DEFAULT 'CONFIRMED' CHECK (status IN ('CONFIRMED', 'CANCELLED')),
  total_minor INTEGER NOT NULL CHECK (total_minor > 0),
  currency    TEXT    NOT NULL REFERENCES currencies(code),
  created_at  TEXT    NOT NULL DEFAULT iso_now(),
  updated_at  TEXT    NOT NULL DEFAULT iso_now(),
  CHECK (check_out > check_in)
);
CREATE INDEX idx_hotel_bookings_room_dates ON hotel_bookings(room_id, check_in, check_out);
CREATE INDEX idx_hotel_bookings_user ON hotel_bookings(user_id);

-- ============================================================ MÜŞTƏRİLƏR, KİTAB, MUSİQİ
CREATE TABLE customers (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  first_name TEXT    NOT NULL,
  last_name  TEXT    NOT NULL,
  email      TEXT    NOT NULL UNIQUE,
  phone      TEXT,
  city       TEXT,
  active     INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  created_at TEXT    NOT NULL DEFAULT iso_now(),
  updated_at TEXT    NOT NULL DEFAULT iso_now()
);
CREATE INDEX idx_customers_city ON customers(city);

CREATE TABLE books (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  title       TEXT    NOT NULL,
  author      TEXT    NOT NULL,
  genre       TEXT    NOT NULL,
  year        INTEGER CHECK (year BETWEEN 1000 AND 2100),
  description TEXT    NOT NULL,
  rating      DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK (rating BETWEEN 0 AND 5),
  pages       INTEGER NOT NULL CHECK (pages > 0)
);
CREATE INDEX idx_books_author ON books(author);
CREATE INDEX idx_books_genre ON books(genre);

CREATE TABLE book_reviews (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  book_id    INTEGER NOT NULL REFERENCES books(id) ON DELETE CASCADE,
  user_id    INTEGER NOT NULL REFERENCES users(id),
  rating     INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment    TEXT,
  created_at TEXT    NOT NULL DEFAULT iso_now(),
  UNIQUE (book_id, user_id)
);

CREATE TABLE tracks (
  id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  youtube_id   TEXT    NOT NULL UNIQUE CHECK (length(youtube_id) = 11),
  title        TEXT    NOT NULL,
  artist       TEXT    NOT NULL,
  genre        TEXT    NOT NULL,
  duration_sec INTEGER NOT NULL CHECK (duration_sec > 0)
);
CREATE INDEX idx_tracks_artist ON tracks(artist);

CREATE TABLE playlists (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name       TEXT    NOT NULL,
  created_at TEXT    NOT NULL DEFAULT iso_now()
);
CREATE INDEX idx_playlists_user ON playlists(user_id);

CREATE TABLE playlist_tracks (
  playlist_id INTEGER NOT NULL REFERENCES playlists(id) ON DELETE CASCADE,
  track_id    INTEGER NOT NULL REFERENCES tracks(id),
  position    INTEGER NOT NULL CHECK (position >= 1),
  PRIMARY KEY (playlist_id, track_id)
);

CREATE TABLE play_history (
  id        INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id   INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  track_id  INTEGER NOT NULL REFERENCES tracks(id),
  played_at TEXT    NOT NULL DEFAULT iso_now()
);
CREATE INDEX idx_play_history_user ON play_history(user_id, played_at);

-- ============================================================ TEXNİKİ
CREATE TABLE idempotency_keys (
  key             TEXT    NOT NULL,
  user_id         INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  endpoint        TEXT    NOT NULL,
  request_hash    TEXT    NOT NULL,
  response_status INTEGER NOT NULL,
  response_body   TEXT    NOT NULL,
  created_at      TEXT    NOT NULL DEFAULT iso_now(),
  expires_at      TEXT    NOT NULL,
  PRIMARY KEY (key, user_id, endpoint)
);

CREATE TABLE audit_log (
  id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    INTEGER REFERENCES users(id),
  action     TEXT    NOT NULL,
  entity     TEXT    NOT NULL,
  entity_id  TEXT    NOT NULL,
  details    TEXT    CHECK (details IS NULL OR (details::jsonb) IS NOT NULL),
  ip         TEXT,
  request_id TEXT,
  created_at TEXT    NOT NULL DEFAULT iso_now()
);
CREATE INDEX idx_audit_entity ON audit_log(entity, entity_id);

CREATE TABLE request_log (
  id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  request_id  TEXT    NOT NULL,
  user_id     INTEGER,
  method      TEXT    NOT NULL,
  path        TEXT    NOT NULL,
  route       TEXT,
  status      INTEGER NOT NULL,
  duration_ms INTEGER NOT NULL,
  ip          TEXT,
  created_at  TEXT    NOT NULL DEFAULT iso_now()
);
CREATE INDEX idx_request_log_created ON request_log(created_at);
CREATE INDEX idx_request_log_user ON request_log(user_id, created_at);

CREATE TABLE rate_limit_counters (
  subject      TEXT    NOT NULL,
  window_start TEXT    NOT NULL,
  count        INTEGER NOT NULL DEFAULT 0 CHECK (count >= 0),
  PRIMARY KEY (subject, window_start)
);

-- ============================================================ TRIGGERS
CREATE FUNCTION fn_cards_status_history() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.status <> NEW.status THEN
    INSERT INTO card_status_history (card_id, old_status, new_status, reason, changed_by, changed_at)
    VALUES (NEW.id, OLD.status, NEW.status, NEW.status_reason, NEW.status_changed_by, NEW.updated_at);
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_cards_status_history AFTER UPDATE OF status ON cards
  FOR EACH ROW EXECUTE FUNCTION fn_cards_status_history();

CREATE FUNCTION fn_transactions_audit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO audit_log (user_id, action, entity, entity_id, details, created_at)
  SELECT a.owner_id, 'TRANSACTION_' || NEW.type, 'transactions', NEW.id::text,
         jsonb_build_object('accountId', NEW.account_id, 'amountMinor', NEW.amount_minor,
                            'currency', NEW.currency, 'transferId', NEW.transfer_id)::text,
         NEW.created_at
  FROM accounts a WHERE a.id = NEW.account_id;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_transactions_audit AFTER INSERT ON transactions
  FOR EACH ROW EXECUTE FUNCTION fn_transactions_audit();

-- ============================================================ VIEWS
CREATE VIEW v_account_balances AS
SELECT a.id AS account_id, a.owner_id, u.username, u.full_name AS owner_name, a.type, a.currency, a.balance_minor,
       ROUND(a.balance_minor / 100.0, 2) AS balance,
       (SELECT COUNT(*) FROM transactions t WHERE t.account_id = a.id) AS transaction_count,
       a.opened_at
FROM accounts a JOIN users u ON u.id = a.owner_id;

CREATE VIEW v_card_overview AS
SELECT c.id AS card_id, u.username AS owner, c.brand, '**** ' || c.last4 AS masked_number, c.status, c.status_reason,
       c.account_id, a.currency, ROUND(c.daily_limit_minor / 100.0, 2) AS daily_limit, c.expires_at,
       (SELECT h.changed_at FROM card_status_history h WHERE h.card_id = c.id ORDER BY h.changed_at DESC, h.id DESC LIMIT 1) AS last_status_change_at,
       (SELECT COUNT(*) FROM card_status_history h WHERE h.card_id = c.id) AS status_change_count
FROM cards c JOIN users u ON u.id = c.owner_id JOIN accounts a ON a.id = c.account_id;

CREATE VIEW v_flight_search AS
SELECT f.id AS flight_id, f.flight_no, f.airline_name, f.from_code, fa.city AS from_city, f.to_code, ta.city AS to_city,
       substr(f.depart_at, 1, 10) AS depart_date, f.depart_at, f.arrive_at, f.duration_min, f.stops,
       ROUND(f.price_minor / 100.0, 2) AS price, f.currency, f.seats_left,
       CASE WHEN f.seats_left = 0 THEN 1 ELSE 0 END AS sold_out
FROM flights f JOIN airports fa ON fa.code = f.from_code JOIN airports ta ON ta.code = f.to_code;

CREATE VIEW v_hotel_availability AS
SELECT r.id AS room_id, h.id AS hotel_id, h.name AS hotel_name, h.city, h.stars, r.room_type, r.capacity,
       ROUND(r.price_per_night_minor / 100.0, 2) AS price_per_night, h.currency,
       EXISTS (SELECT 1 FROM hotel_bookings b WHERE b.room_id = r.id AND b.status = 'CONFIRMED'
                 AND b.check_in <= to_char(CURRENT_DATE, 'YYYY-MM-DD') AND b.check_out > to_char(CURRENT_DATE, 'YYYY-MM-DD')) AS occupied_today,
       (SELECT MIN(b.check_in) FROM hotel_bookings b WHERE b.room_id = r.id AND b.status = 'CONFIRMED'
          AND b.check_in > to_char(CURRENT_DATE, 'YYYY-MM-DD')) AS next_booking_check_in,
       (SELECT COUNT(*) FROM hotel_bookings b WHERE b.room_id = r.id AND b.status = 'CONFIRMED'
          AND b.check_out > to_char(CURRENT_DATE, 'YYYY-MM-DD')) AS upcoming_bookings
FROM hotel_rooms r JOIN hotels h ON h.id = r.hotel_id;

CREATE VIEW v_api_usage_by_endpoint AS
SELECT method, COALESCE(route, path) AS endpoint, COUNT(*) AS calls, ROUND(AVG(duration_ms), 1) AS avg_ms, MAX(duration_ms) AS max_ms,
       SUM(CASE WHEN status BETWEEN 200 AND 399 THEN 1 ELSE 0 END) AS ok_count,
       SUM(CASE WHEN status BETWEEN 400 AND 499 THEN 1 ELSE 0 END) AS client_errors,
       SUM(CASE WHEN status >= 500 THEN 1 ELSE 0 END) AS server_errors,
       MAX(created_at) AS last_called_at
FROM request_log GROUP BY method, COALESCE(route, path);
